-- Payer profiles
INSERT INTO ambuintake.payers (code, name, kind, parent_code, description, requires_medical_necessity, prior_auth, prior_auth_note, certification, documentation, alternate_transport, contact_name, contact_phone, contact_fax, contact_email, contact_url, sort_order, active, is_system)
VALUES ('medicare', 'Original Medicare (Part B)', 'payer', NULL, 'Fee-for-service Medicare. Coverage criteria: 42 CFR 410.40 and Medicare Benefit Policy Manual, Ch. 10.', true, '{"emergency":"not_required","non_emergency":"not_required","repetitive":"varies"}', 'Repetitive, scheduled non-emergent transports may be subject to CMS prior authorization depending on your Medicare Administrative Contractor (MAC). Check your MAC.', 'Physician Certification Statement (PCS). Repetitive scheduled transports: signed and dated no earlier than 60 days before the transport. Non-repetitive transports: may be obtained up to 48 hours after the transport.', '["Bed-confinement alone is not sufficient — document the specific condition that makes other transport unsafe.","If the patient requests a non-emergency transport that is expected to be denied, issue an Advance Beneficiary Notice of Noncoverage (ABN) before transport."]', 'Original Medicare does not cover wheelchair-van or other non-ambulance transport. Check for Medicaid or other secondary coverage.', 'Medicare Administrative Contractor (MAC)', '', '', '', '', 10, true, true)
ON CONFLICT (code) DO NOTHING;

INSERT INTO ambuintake.payers (code, name, kind, parent_code, description, requires_medical_necessity, prior_auth, prior_auth_note, certification, documentation, alternate_transport, contact_name, contact_phone, contact_fax, contact_email, contact_url, sort_order, active, is_system)
VALUES ('medicare_advantage', 'Medicare Advantage (Part C)', 'payer', NULL, 'Private Medicare plans. Plans must cover ambulance services that Original Medicare covers and follow its coverage criteria (42 CFR 422.101), but may require prior authorization for non-emergency transport.', true, '{"emergency":"not_required","non_emergency":"varies","repetitive":"varies"}', 'Medicare Advantage plans may not require prior authorization for emergency services (42 CFR 422.113). Most plans require it for scheduled non-emergency transport — check the plan.', 'Plan-specific. Document medical necessity as for Original Medicare; most plans also require or accept a PCS.', '["Verify eligibility and the plan name using the member ID card or the plan portal.","Record the plan''s authorization or reference number on the trip.","Out-of-network non-emergency transport may not be covered unless the plan authorizes it."]', 'Many Medicare Advantage plans offer a supplemental transportation benefit (e.g., wheelchair van or rideshare). Refer the caller to the plan''s member services.', 'Plan utilization management (number on member ID card)', '', '', '', '', 20, true, true)
ON CONFLICT (code) DO NOTHING;

INSERT INTO ambuintake.payers (code, name, kind, parent_code, description, requires_medical_necessity, prior_auth, prior_auth_note, certification, documentation, alternate_transport, contact_name, contact_phone, contact_fax, contact_email, contact_url, sort_order, active, is_system)
VALUES ('medicaid', 'Medicaid', 'payer', NULL, 'State Medicaid program (fee-for-service or managed care). Coverage, forms and authorization rules are set by each state — review this profile against your state''s provider manual.', true, '{"emergency":"not_required","non_emergency":"varies","repetitive":"varies"}', 'Most states require prior authorization for non-emergency ambulance transport. Managed-care (MCO) members follow the MCO''s authorization process.', 'State-specific. Most states require a practitioner certification or medical-necessity form for non-emergency ambulance — use your state''s form.', '["Verify Medicaid eligibility for the date of service.","Medicaid is the payer of last resort: if the patient has Medicare or other coverage, bill that payer first."]', 'Medicaid must ensure necessary transportation to covered services (42 CFR 431.53). If ambulance is not indicated, refer the caller to the state''s non-emergency medical transportation (NEMT) broker for wheelchair or ambulatory transport.', 'State Medicaid / NEMT broker', '', '', '', '', 30, true, true)
ON CONFLICT (code) DO NOTHING;

INSERT INTO ambuintake.payers (code, name, kind, parent_code, description, requires_medical_necessity, prior_auth, prior_auth_note, certification, documentation, alternate_transport, contact_name, contact_phone, contact_fax, contact_email, contact_url, sort_order, active, is_system)
VALUES ('commercial', 'Commercial insurance', 'payer', NULL, 'Employer or individual health plans. Coverage criteria and authorization rules are set by each plan''s medical policy.', true, '{"emergency":"not_required","non_emergency":"varies","repetitive":"varies"}', 'Check the plan''s medical policy for non-emergency ambulance authorization requirements.', 'Plan-specific — check the plan''s medical policy.', '["Verify eligibility, benefits, and network status.","Federal No Surprises Act balance-billing protections do not apply to ground ambulance; some states have their own protections."]', 'Check whether the plan covers wheelchair-van or other non-emergency transportation.', 'Plan provider services (number on member ID card)', '', '', '', '', 40, true, true)
ON CONFLICT (code) DO NOTHING;

INSERT INTO ambuintake.payers (code, name, kind, parent_code, description, requires_medical_necessity, prior_auth, prior_auth_note, certification, documentation, alternate_transport, contact_name, contact_phone, contact_fax, contact_email, contact_url, sort_order, active, is_system)
VALUES ('private_pay', 'Private pay (self-pay)', 'payer', NULL, 'The patient or a family member pays directly. No medical-necessity review is required.', false, '{"emergency":"not_required","non_emergency":"not_required","repetitive":"not_required"}', '', '', '["Quote the transport rate and confirm the payment method before scheduling.","Have the patient or responsible party sign the financial responsibility agreement."]', '', '', '', '', '', '', 50, true, true)
ON CONFLICT (code) DO NOTHING;

INSERT INTO ambuintake.payers (code, name, kind, parent_code, description, requires_medical_necessity, prior_auth, prior_auth_note, certification, documentation, alternate_transport, contact_name, contact_phone, contact_fax, contact_email, contact_url, sort_order, active, is_system)
VALUES ('facility_pay', 'Facility pay', 'payer', NULL, 'The sending or receiving facility (hospital, SNF, hospice) pays under its agreement with us. No medical-necessity review is required.', false, '{"emergency":"not_required","non_emergency":"not_required","repetitive":"not_required"}', '', '', '["Confirm the facility has an active billing agreement with us.","Record who at the facility authorized the transport and any purchase-order number."]', '', '', '', '', '', '', 60, true, true)
ON CONFLICT (code) DO NOTHING;

