INSERT INTO ambuintake.questions (code, category, text, guidance, answer_type, options, call_types, payers, criterion, qualifying_answer, triggers, detect_yes, detect_no, depends_on_code, depends_on_answer, priority, sort_order, required, alert_answer, alert_text, alert_level, active, necessity, is_system)
VALUES ('EMG_SCREEN', 'Emergency Screening', 'Is the patient having chest pain, trouble breathing, stroke symptoms, severe bleeding, a seizure, or are they unresponsive right now?', 'Screen every call for an active emergency before continuing with a scheduled-transport intake.', 'yes_no', '[]', '[]', '[]', 'emergency', 'yes', '[]', '["chest pain","can''t breathe","cannot breathe","trouble breathing","difficulty breathing","not breathing","stroke symptoms","slurred speech","facial droop","severe bleeding","bleeding heavily","seizing","having a seizure","unresponsive","passed out"]', '["stable","no distress","resting comfortably","vitals are stable"]', NULL, NULL, 1, 10, true, 'yes', 'Possible emergency: transfer to 911 / emergency dispatch per protocol.', 'critical', true, false, true)
ON CONFLICT (code) DO NOTHING;

INSERT INTO ambuintake.questions (code, category, text, guidance, answer_type, options, call_types, payers, criterion, qualifying_answer, triggers, detect_yes, detect_no, depends_on_code, depends_on_answer, priority, sort_order, required, alert_answer, alert_text, alert_level, active, necessity, is_system)
VALUES ('TX_REASON', 'Transport Details', 'What is the reason for transport and the patient''s primary diagnosis?', 'Document the condition that makes ambulance transport necessary — not just the destination appointment.', 'text', '[]', '[]', '[]', 'info', NULL, '[]', '[]', '[]', NULL, NULL, 1, 20, true, NULL, NULL, NULL, true, false, true)
