INSERT INTO ambuintake.questions (code, category, text, guidance, answer_type, options, call_types, payers, criterion, qualifying_answer, triggers, detect_yes, detect_no, depends_on_code, depends_on_answer, priority, sort_order, required, alert_answer, alert_text, alert_level, active, necessity, is_system)
VALUES ('TX_DEST_TYPE', 'Transport Details', 'What type of facility is the patient going to?', 'Covered destinations include hospitals, critical access hospitals, SNFs, the beneficiary''s home, and dialysis facilities for ESRD patients. Physician offices are generally not covered destinations.', 'choice', '["Hospital — emergency / inpatient","Hospital — outpatient / diagnostic","Skilled nursing facility","Patient residence","Dialysis facility","Physician office / clinic","Other"]', '[]', '[]', 'info', NULL, '[]', '[]', '[]', NULL, NULL, 1, 30, true, 'Physician office / clinic', 'Physician offices are generally not a covered ambulance destination under Medicare.', 'warning', true, true, true)
