INSERT INTO ambuintake.questions (code, category, text, guidance, answer_type, options, call_types, payers, criterion, qualifying_answer, triggers, detect_yes, detect_no, depends_on_code, depends_on_answer, priority, sort_order, required, alert_answer, alert_text, alert_level, active, necessity, is_system)
VALUES ('TX_NEAREST', 'Transport Details', 'Is the destination the nearest appropriate facility that can provide the care the patient needs?', 'Medicare covers mileage only to the nearest appropriate facility. If farther, document why closer facilities cannot provide the care.', 'yes_no', '[]', '[]', '[]', 'info', NULL, '[]', '[]', '[]', NULL, NULL, 2, 40, false, 'no', 'Destination is not the nearest appropriate facility — excess mileage may be non-covered. Document the reason.', 'warning', true, true, true)
