INSERT INTO ambuintake.questions (code, category, text, guidance, answer_type, options, call_types, payers, criterion, qualifying_answer, triggers, detect_yes, detect_no, depends_on_code, depends_on_answer, priority, sort_order, required, alert_answer, alert_text, alert_level, active, necessity, is_system)
VALUES ('TX_REPETITIVE', 'Transport Details', 'Will the patient need 3 or more round trips in 10 days, or at least one trip a week for 3 weeks or more (e.g., dialysis, wound care, chemotherapy)?', 'Repetitive, scheduled non-emergent transports require a PCS dated no earlier than 60 days before the transport and may require prior authorization.', 'yes_no', '[]', '["non_emergency","repetitive"]', '[]', 'info', NULL, '[]', '["dialysis","three times a week","3 times a week","every week","weekly","monday wednesday friday","chemotherapy","chemo","radiation therapy","wound care"]', '["one time","one-time","just this once","single trip"]', NULL, NULL, 2, 50, false, 'yes', 'Repetitive transport: PCS must be dated within 60 days prior; check prior-authorization requirements.', 'info', true, true, true)
ON CONFLICT (code) DO NOTHING;

INSERT INTO ambuintake.questions (code, category, text, guidance, answer_type, options, call_types, payers, criterion, qualifying_answer, triggers, detect_yes, detect_no, depends_on_code, depends_on_answer, priority, sort_order, required, alert_answer, alert_text, alert_level, active, necessity, is_system)
VALUES ('TX_OTHER_MEANS', 'Transport Details', 'Could the patient safely travel by any other means (wheelchair van, car, taxi) without endangering their health?', 'Ambulance transport is covered only when other means of transportation are contraindicated by the patient''s condition.', 'yes_no', '[]', '[]', '[]', 'disqualifier', 'yes', '[]', '["wheelchair van","rides in a car","can ride in a car","family can drive","family could drive","take a taxi","takes a taxi","by car"]', '["too unstable","cannot ride in a car","can''t ride in a car","needs a stretcher","needs stretcher","must be on a stretcher"]', NULL, NULL, 1, 60, true, NULL, NULL, NULL, true, true, true)
